  const reclaimed = acquireProviderProcessAdmission({ root: join(root, 'leaked'), env: { ...process.env, LATTICE_HOST_RUN_MAX_CONCURRENT: '1' }, host: 'claude', storyId: 'B-cap', agentType: 'after-crash' });
  assert.equal(reclaimed.admitted, true, 'a crashed holder pid must be reconciled and its slot reclaimed');
